def _act_fn(v, ACT: tl.constexpr):
    # activations computed in fp32 (mirrors torch float opmath then cast)
    # ACT: 0=relu, 1=silu, 2=fastgelu, 3=gelu(tanh), 4=none
    if ACT == 0:
        return tl.maximum(v, 0.0)
    if ACT == 1:
        return v * (1.0 / (1.0 + tl.exp(-v)))
    if ACT == 2:
        return v * (1.0 / (1.0 + tl.exp(-1.7 * v)))
    if ACT == 4:
