    # tanh gelu: 0.5*v*(1+tanh(a*v*(1+0.044715*v^2))), numerically stable tanh
    a: tl.constexpr = 0.7978845608028654
    av = a * v * (1.0 + 0.044715 * v * v)
    e = tl.exp(-2.0 * tl.abs(av))
    tanh_v = tl.where(av >= 0.0, 1.0, -1.0) * (1.0 - 2.0 / (1.0 + e))
    return 0.5 * v * (1.0 + tanh_v)' --old_str '@triton.jit
